107	+// Generates veashi-sdk/vea/testnet.json from the hardhat-deploy files in contracts/deployments.
108	+// Run with `yarn extract:vea`. Only `*Testnet` deployments are read; Devnet ones are ignored.
109	+const fs = require("fs");
110	+const path = require("path");
111	+
112	+const DEPLOYMENTS_DIR = path.resolve(__dirname, "../../contracts/deployments");
113	+const OUTPUT_FILE = path.resolve(__dirname, "../vea/testnet.json");
114	+
115	+// Expected chain id per network; checked against contracts/deployments/<network>/.chainId.
116	+const NETWORK_CHAIN_IDS = {
117	+  arbitrumSepolia: 421614,
118	+  sepolia: 11155111,
119	+  chiado: 10200,
120	+};
121	+
122	+// Routes whose outbox is reached through a router on an intermediate chain.
123	+const ROUTES_WITH_ROUTER = new Set(["ArbToGnosis"]);
124	+
125	+const FILE_PATTERN = /^(VeaInbox|VeaOutbox|Router)([A-Za-z]+To[A-Za-z]+)Testnet\.json$/;
126	+const ROLES = { VeaInbox: "inbox", VeaOutbox: "outbox", Router: "router" };
127	+
128	+function checkChainId(network, dir) {
129	+  const file = path.join(dir, ".chainId");
130	+  if (!fs.existsSync(file)) throw new Error(`${network}: missing ${path.relative(process.cwd(), file)}`);
131	+  const chainId = Number(fs.readFileSync(file, "utf8").trim());
132	+  if (chainId !== NETWORK_CHAIN_IDS[network]) {
133	+    throw new Error(`${network}: .chainId is ${chainId}, expected ${NETWORK_CHAIN_IDS[network]}`);
134	+  }
135	+}
136	+
137	+function readDeployments() {
138	+  // route name (e.g. "ArbToEth") -> { inbox, outbox, router }
139	+  const byRoute = {};
140	+  for (const network of Object.keys(NETWORK_CHAIN_IDS).sort()) {
141	+    const dir = path.join(DEPLOYMENTS_DIR, network);
142	+    if (!fs.existsSync(dir)) continue;
143	+    checkChainId(network, dir);
144	+    for (const file of fs.readdirSync(dir).sort()) {
145	+      const match = FILE_PATTERN.exec(file);
146	+      if (!match) continue;
147	+      const [, kind, routeName] = match;
148	+      const role = ROLES[kind];
149	+      const { address } = JSON.parse(fs.readFileSync(path.join(dir, file), "utf8"));
150	+      if (typeof address !== "string" || !/^0x[0-9a-fA-F]{40}$/.test(address)) {
151	+        throw new Error(`${network}/${file}: missing or invalid address`);
152	+      }
153	+      const route = (byRoute[routeName] = byRoute[routeName] || {});
154	+      if (route[role]) {
155	+        throw new Error(`${routeName}: duplicate ${role} (${route[role].network} and ${network})`);
156	+      }
157	+      route[role] = { address, contract: file.replace(/\.json$/, ""), network };
158	+    }
159	+  }
160	+  return byRoute;
161	+}
162	+
163	+function buildRoutes(byRoute) {
164	+  const routes = {};
165	+  for (const routeName of Object.keys(byRoute).sort()) {
166	+    const { inbox, outbox, router } = byRoute[routeName];
167	+    if (!inbox || !outbox) continue;
168	+
169	+    const needsRouter = ROUTES_WITH_ROUTER.has(routeName);
170	+    if (needsRouter && !router) throw new Error(`${routeName}: route needs a router but has no testnet router`);
171	+    if (!needsRouter && router) throw new Error(`${routeName}: unexpected router; add the route to ROUTES_WITH_ROUTER`);
172	+
173	+    const key = `${NETWORK_CHAIN_IDS[inbox.network]}-${NETWORK_CHAIN_IDS[outbox.network]}`;
174	+    if (routes[key]) throw new Error(`${key}: more than one testnet route`);
175	+    routes[key] = router ? { inbox, outbox, router } : { inbox, outbox };
176	+  }
177	+  return routes;
178	+}
179	+
180	+function sortKeys(value) {
181	+  if (Array.isArray(value)) return value.map(sortKeys);
182	+  if (value && typeof value === "object") {
183	+    return Object.fromEntries(
184	+      Object.keys(value)
185	+        .sort()
186	+        .map((key) => [key, sortKeys(value[key])])
187	+    );
188	+  }
189	+  return value;
190	+}
191	+
192	+const routes = sortKeys(buildRoutes(readDeployments()));
193	+fs.writeFileSync(OUTPUT_FILE, JSON.stringify(routes, null, 2) + "\n");
194	+console.log(
195	+  `✅ Wrote ${Object.keys(routes).length} Vea testnet routes to ${path.relative(process.cwd(), OUTPUT_FILE)}`
196	+);
