229	+import VEA_TESTNET_ROUTES from "./vea/testnet.json";
230	+import type { VeaRouteAddresses, VeaRouteFile } from "./types";
231	+
232	+/* --------------------------------------------------
233	+   Internal helper
234	+-------------------------------------------------- */
235	+
236	+// Generated by `yarn extract:vea` from contracts/deployments (testnet only).
237	+const VEA_ROUTES = VEA_TESTNET_ROUTES as Record<string, VeaRouteFile>;
238	+
239	+function getVeaRouteFile(sourceChainId: number, destinationChainId: number): VeaRouteFile | undefined {
240	+  const key = `${sourceChainId}-${destinationChainId}`;
241	+  return Object.prototype.hasOwnProperty.call(VEA_ROUTES, key) ? VEA_ROUTES[key] : undefined;
242	+}
243	+
244	+/* --------------------------------------------------
245	+   Public getters – Vea (testnet)
246	+-------------------------------------------------- */
247	+
248	+export function getVeaRoute(sourceChainId: number, destinationChainId: number): VeaRouteAddresses | undefined {
249	+  const route = getVeaRouteFile(sourceChainId, destinationChainId);
250	+  if (!route) return undefined;
251	+
252	+  const { inbox, outbox, router } = route;
253	+  return router
254	+    ? { inbox: inbox.address, outbox: outbox.address, router: router.address }
255	+    : { inbox: inbox.address, outbox: outbox.address };
256	+}
257	+
258	+export function getVeaInbox(sourceChainId: number, destinationChainId: number): `0x${string}` | undefined {
259	+  return getVeaRouteFile(sourceChainId, destinationChainId)?.inbox.address;
260	+}
261	+
262	+export function getVeaOutbox(sourceChainId: number, destinationChainId: number): `0x${string}` | undefined {
263	+  return getVeaRouteFile(sourceChainId, destinationChainId)?.outbox.address;
264	+}
265	+
266	+export function getVeaRouter(sourceChainId: number, destinationChainId: number): `0x${string}` | undefined {
267	+  return getVeaRouteFile(sourceChainId, destinationChainId)?.router?.address;
268	+}
269	+
270	+export function getVeaRoutes(): string[] {
271	+  return Object.keys(VEA_ROUTES);
272	+}
