24	const path = require('path');
25	
26	const collectedFiles = new Set();
27	
28	/**
29	 * CORE LOGIC: 
30	 * We define exactly what we want and where it goes.
31	 */
32	const COPY_PLAN = [
33	    // HASHI CORE -> Target Root
34	    { srcBase: '$HASHI_SRC', file: 'Hashi.sol', destSubDir: '' },
35	    { srcBase: '$HASHI_SRC', file: 'Yaho.sol', destSubDir: '' },
36	    { srcBase: '$HASHI_SRC', file: 'Yaru.sol', destSubDir: '' },
37	
